 * (`issue:update`) and a creation in the target (`issue:create`, a live
 * project, the per-project issue quota). Every gate runs before the first
 * write, so a refused move changes nothing. Publishes `issue.moved` and only
 * that; a move within the same project is a no-op and publishes nothing.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  // Scoped to the actor's organization: a project of another workspace is
  // simply not found.
  const target = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", target.id, target);
  assertCan(actor, "issue:create", projectResource(target));

  if (before.projectId === target.id) return before;

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, target.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${target.key}`,
    );
  }

  const after = await issueRepo.moveIssueToProject(
    input.orgId,
    before.id,
    target.id,
  );

  // The search index denormalises the project. Re-file the document as part
  // of the move itself rather than leaving it to a subscriber, so a search
  // scoped to either project is right the moment the move returns.
  await searchRepo.setSearchDocumentProject(
    input.orgId,
    "issue",
    after.id,
    after.projectId,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId: before.projectId,
    toProjectId: after.projectId,
    fromNumber: before.number,
    toNumber: after.number,
  });

  return after;
}

