/**
 * Moving an issue to another project of the same workspace (ADR 0011):
 * numbering, the two permissions, the target's quota, the audit entry, the
 * search index and the single `issue.moved` event.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { moveIssueToProjectSchema } from "@/schemas/issue";
import { activityActionSchema, activityFilterSchema } from "@/schemas/activity";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let source: Project;
let target: Project;
const detachers: Unsubscribe[] = [];
let projectSeq = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function newProject(owner: Tenant = tenant): Promise<Project> {
  projectSeq += 1;
  return projectRepo.insertProject({
    orgId: owner.org.id,
    name: `Project ${projectSeq}`,
    slug: `project-${projectSeq}`,
    key: `P${projectSeq}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

function create(project: Project, title: string, owner: Tenant = tenant) {
  return issueService.createIssue(
    owner.actors.member,
    issueInput(owner.org.id, project.id, { title }),
  );
}

function move(issueId: string, toProjectId: string, actor = tenant.actors.member) {
  return issueService.moveIssueToProject(actor, {
    orgId: actor.orgId,
    issueId: issueId as never,
    toProjectId: toProjectId as never,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movers", "growth");
  other = await createTenant("bystanders", "growth");
  source = tenant.project;
  target = await newProject();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("moveIssueToProject — numbering", () => {
  it("takes the target project's next number and stores the new project", async () => {
    await create(target, "Already in the target");
    const issue = await create(source, "Filed in the wrong place");

    const moved = await move(issue.id, target.id);

    expect(moved.id).toBe(issue.id);
    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(2);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(moved);
  });

  it("retires the number the issue leaves behind", async () => {
    const from = await newProject();
    const to = await newProject();

    await create(from, "one");
    await create(from, "two");
    const third = await create(from, "three");
    expect(third.number).toBe(3);

    await move(third.id, to.id);

    await expect(issueRepo.nextIssueNumber(tenant.org.id, from.id)).resolves.toBe(4);
    const next = await create(from, "four");
    expect(next.number).toBe(4);
  });

  it("gives a fresh number to an issue that is moved away and back", async () => {
    const from = await newProject();
    const to = await newProject();

    const issue = await create(from, "boomerang");
    expect(issue.number).toBe(1);

    const away = await move(issue.id, to.id);
    expect(away.number).toBe(1);

    const back = await move(issue.id, from.id);
    expect(back.projectId).toBe(from.id);
    expect(back.number).toBe(2);

    // …and the number it used in the other project is gone for good there too.
    const fresh = await create(to, "after the boomerang");
    expect(fresh.number).toBe(2);
  });

  it("never reuses a number even when the project is left empty", async () => {
    const from = await newProject();
    const to = await newProject();

    const only = await create(from, "the only one");
    await move(only.id, to.id);

    const next = await create(from, "the next one");
    expect(next.number).toBe(2);
  });
});

describe("moveIssueToProject — what stays", () => {
  it("leaves the issue's content, people, labels, comments and attachments alone", async () => {
    const to = await newProject();
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "moves-with-it",
      color: "#ef4444",
      description: null,
    });
    const parent = await create(source, "The parent stays put");

    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, source.id, {
        title: "Fully loaded",
        assigneeId: tenant.userIds.admin,
        dueAt: "2026-12-01T00:00:00.000Z",
      }),
      description: "With a description",
      status: "in_review",
      priority: "high",
      estimate: 5,
      parentId: parent.id,
      labelIds: [label.id],
    });
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Comes along",
      parentId: null,
      mentionedUserIds: [],
    });
    const attachmentsBefore = await attachmentRepo.listAttachments(tenant.org.id, issue.id);

    const moved = await move(issue.id, to.id);

    expect(moved).toMatchObject({
      title: issue.title,
      description: issue.description,
      status: issue.status,
      priority: issue.priority,
      authorId: issue.authorId,
      assigneeId: issue.assigneeId,
      estimate: issue.estimate,
      dueAt: issue.dueAt,
      parentId: parent.id,
      labelIds: [label.id],
      startedAt: issue.startedAt,
      completedAt: issue.completedAt,
      createdAt: issue.createdAt,
      archivedAt: null,
    });

    const detail = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(detail.labels.map((l) => l.id)).toEqual([label.id]);
    expect(detail.commentCount).toBe(1);
    expect(detail.attachmentCount).toBe(attachmentsBefore.length);

    // The parent it is linked to was not dragged along.
    const parentAfter = await issueRepo.findIssueById(tenant.org.id, parent.id);
    expect(parentAfter?.projectId).toBe(source.id);
  });

  it("shows up on the target's board and list and leaves the source's", async () => {
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Board hopper");

    await move(issue.id, to.id);

    const ids = async (projectId: Project["id"]) =>
      (await issueService.getBoard(tenant.actors.member, tenant.org.id, projectId))
        .flatMap((column) => column.issues.map((i) => i.id));
    await expect(ids(from.id)).resolves.toEqual([]);
    await expect(ids(to.id)).resolves.toEqual([issue.id]);

    const list = async (projectId: Project["id"]) =>
      (
        await issueService.listIssues(tenant.actors.member, {
          orgId: tenant.org.id,
          projectId,
          limit: 25,
          cursor: null,
        })
      ).items.map((i) => i.id);
    await expect(list(from.id)).resolves.toEqual([]);
    await expect(list(to.id)).resolves.toEqual([issue.id]);
  });
});

describe("moveIssueToProject — refusals change nothing", () => {
  async function expectUntouched(issueId: string, before: unknown) {
    await expect(issueRepo.findIssueById(tenant.org.id, issueId as never)).resolves.toEqual(before);
  }

  it("requires being allowed to edit the issue", async () => {
    const issue = await create(source, "Not the viewer's");
    const seen = capture("issue.moved");

    await expect(move(issue.id, target.id, tenant.actors.viewer)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );

    await expectUntouched(issue.id, issue);
    expect(seen).toHaveLength(0);
  });

  it("also requires being allowed to create issues in the target", async () => {
    // The viewer may edit an issue assigned to them, but cannot create issues.
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, source.id, {
        title: "Assigned to the viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const numberBefore = await issueRepo.nextIssueNumber(tenant.org.id, target.id);

    const error: unknown = await move(issue.id, target.id, tenant.actors.viewer).catch(
      (caught: unknown) => caught,
    );

    expect(error).toBeInstanceOf(PermissionDeniedError);
    expect((error as PermissionDeniedError).action).toBe("issue:create");
    await expectUntouched(issue.id, issue);
    await expect(issueRepo.nextIssueNumber(tenant.org.id, target.id)).resolves.toBe(numberBefore);
  });

  it("applies the target project's issue quota", async () => {
    const free = await createTenant("frugalmovers", "free");
    const full = await projectRepo.insertProject({
      orgId: free.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, full.id, { title: `Seed ${number}` }),
        free.userIds.member,
        number,
      );
    }
    const issue = await create(free.project, "One too many", free);
    const seen = capture("issue.moved");

    await expect(move(issue.id, full.id, free.actors.member)).rejects.toThrow(
      /allows no more issues/,
    );

    await expect(issueRepo.findIssueById(free.org.id, issue.id)).resolves.toEqual(issue);
    await expect(issueRepo.countIssues(free.org.id, full.id)).resolves.toBe(100);
    await expect(issueRepo.nextIssueNumber(free.org.id, full.id)).resolves.toBe(101);
    expect(seen).toHaveLength(0);
  });

  it("does not find a project of another workspace", async () => {
    const issue = await create(source, "Stays in its workspace");

    await expect(move(issue.id, other.project.id)).rejects.toBeInstanceOf(NotFoundError);
    await expectUntouched(issue.id, issue);
  });

  it("refuses an actor from another workspace", async () => {
    const issue = await create(source, "Not yours");

    await expect(
      issueService.moveIssueToProject(other.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toProjectId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expectUntouched(issue.id, issue);
  });

  it("refuses an archived issue and an archived target", async () => {
    const archived = await create(source, "Archived first");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);
    await expect(move(archived.id, target.id)).rejects.toBeInstanceOf(AlreadyArchivedError);

    const gone = await newProject();
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: gone.id,
      archiveIssues: true,
    });
    const issue = await create(source, "Nowhere to go");
    await expect(move(issue.id, gone.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expectUntouched(issue.id, issue);
  });
});

describe("moveIssueToProject — announcing", () => {
  it("publishes exactly one issue.moved, on behalf of the mover", async () => {
    const issue = await create(source, "Announce me");
    const moved = capture("issue.moved");
    const others = [
      capture("issue.created"),
      capture("issue.updated"),
      capture("issue.archived"),
      capture("issue.status_changed"),
      capture("issue.assigned"),
    ];

    const after = await move(issue.id, target.id, tenant.actors.admin);

    expect(moved).toHaveLength(1);
    expect(moved[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      issueId: issue.id,
      fromProjectId: source.id,
      toProjectId: target.id,
      fromNumber: issue.number,
      toNumber: after.number,
    });
    expect(moved[0]?.occurredAt).toEqual(expect.any(String));
    for (const seen of others) expect(seen).toHaveLength(0);
  });

  it("changes nothing and publishes nothing within the same project", async () => {
    const issue = await create(source, "Going nowhere");
    const numberBefore = await issueRepo.nextIssueNumber(tenant.org.id, source.id);
    const moved = capture("issue.moved");

    const result = await move(issue.id, source.id);

    expect(result).toEqual(issue);
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(issue);
    await expect(issueRepo.nextIssueNumber(tenant.org.id, source.id)).resolves.toBe(numberBefore);
    expect(moved).toHaveLength(0);
  });
});

describe("moveIssueToProject — audit log and search", () => {
  it("records the move once under the target and leaves older entries alone", async () => {
    detachers.push(registerActivityListeners());
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Audited move");

    const after = await move(issue.id, to.id);

    const history = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    const created = history.filter((event) => event.action === "issue.created");
    const moves = history.filter((event) => event.action === "issue.moved");

    expect(created).toHaveLength(1);
    expect(created[0]?.projectId).toBe(from.id);

    expect(moves).toHaveLength(1);
    expect(moves[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: to.id,
      metadata: {
        fromProjectId: from.id,
        toProjectId: to.id,
        fromNumber: issue.number,
        toNumber: after.number,
      },
    });
  });

  it("accepts issue.moved as an audit-log filter", () => {
    expect(activityActionSchema.parse("issue.moved")).toBe("issue.moved");
    expect(
      activityFilterSchema.safeParse({ orgId: tenant.org.id, action: ["issue.moved"] }).success,
    ).toBe(true);
  });

  it("is found by a search inside the target project and not the source", async () => {
    detachers.push(searchService.registerSearchListeners());
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Quebec relocation marker");

    const hits = async (projectId: Project["id"]) =>
      (
        await searchService.search(tenant.actors.member, {
          orgId: tenant.org.id,
          q: "Quebec",
          kinds: ["issue"],
          projectId,
          limit: 25,
          cursor: null,
        })
      ).items.map((hit) => hit.id);

    await expect(hits(from.id)).resolves.toEqual([issue.id]);

    await move(issue.id, to.id);

    await expect(hits(from.id)).resolves.toEqual([]);
    await expect(hits(to.id)).resolves.toEqual([issue.id]);
  });

  it("re-files the search document even with no index subscriber attached", async () => {
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Romeo relocation marker");
    await searchService.indexIssue(tenant.org.id, issue);

    await move(issue.id, to.id);

    const page = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Romeo",
      kinds: ["issue"],
      projectId: from.id,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toEqual([]);
  });
});

describe("moveIssueToProjectSchema", () => {
  it("requires three ULIDs", () => {
    const ok = {
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
      toProjectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
    };
    expect(moveIssueToProjectSchema.parse(ok)).toEqual(ok);
    expect(moveIssueToProjectSchema.safeParse({ ...ok, toProjectId: "nope" }).success).toBe(false);
    expect(moveIssueToProjectSchema.safeParse({ orgId: ok.orgId, issueId: ok.issueId }).success).toBe(false);
  });
});

