describe("moveIssueToProject — audit log and search", () => {
  it("records the move once under the target and leaves older entries alone", async () => {
    detachers.push(registerActivityListeners());
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Audited move");

    const after = await move(issue.id, to.id);

    const history = await activityRepo.listActivityForSubject(tenant.org.id, "issue", issue.id);
    const created = history.filter((event) => event.action === "issue.created");
    const moves = history.filter((event) => event.action === "issue.moved");

    expect(created).toHaveLength(1);
    expect(created[0]?.projectId).toBe(from.id);

    expect(moves).toHaveLength(1);
    expect(moves[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: to.id,
      metadata: {
        fromProjectId: from.id,
        toProjectId: to.id,
        fromNumber: issue.number,
        toNumber: after.number,
      },
    });
  });

  it("accepts issue.moved as an audit-log filter", () => {
    expect(activityActionSchema.parse("issue.moved")).toBe("issue.moved");
    expect(
      activityFilterSchema.safeParse({ orgId: tenant.org.id, action: ["issue.moved"] }).success,
    ).toBe(true);
  });

  it("is found by a search inside the target project and not the source", async () => {
    detachers.push(searchService.registerSearchListeners());
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Quebec relocation marker");

    const hits = async (projectId: Project["id"]) =>
      (
        await searchService.search(tenant.actors.member, {
          orgId: tenant.org.id,
          q: "Quebec",
          kinds: ["issue"],
          projectId,
          limit: 25,
          cursor: null,
        })
      ).items.map((hit) => hit.id);

    await expect(hits(from.id)).resolves.toEqual([issue.id]);

    await move(issue.id, to.id);

    await expect(hits(from.id)).resolves.toEqual([]);
    await expect(hits(to.id)).resolves.toEqual([issue.id]);
  });

  it("re-files the search document even with no index subscriber attached", async () => {
    const from = await newProject();
    const to = await newProject();
    const issue = await create(from, "Romeo relocation marker");
    await searchService.indexIssue(tenant.org.id, issue);

    await move(issue.id, to.id);

    const page = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Romeo",
      kinds: ["issue"],
      projectId: from.id,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toEqual([]);
  });
});

describe("moveIssueToProjectSchema", () => {
  it("requires three ULIDs", () => {
    const ok = {
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS",
      toProjectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
    };
    expect(moveIssueToProjectSchema.parse(ok)).toEqual(ok);
    expect(moveIssueToProjectSchema.safeParse({ ...ok, toProjectId: "nope" }).success).toBe(false);
    expect(moveIssueToProjectSchema.safeParse({ orgId: ok.orgId, issueId: ok.issueId }).success).toBe(false);
  });
});

