      (await issueService.getBoard(tenant.actors.member, tenant.org.id, projectId))
        .flatMap((column) => column.issues.map((i) => i.id));
    await expect(ids(from.id)).resolves.toEqual([]);
    await expect(ids(to.id)).resolves.toEqual([issue.id]);

    const list = async (projectId: Project["id"]) =>
      (
        await issueService.listIssues(tenant.actors.member, {
          orgId: tenant.org.id,
          projectId,
          limit: 25,
          cursor: null,
        })
      ).items.map((i) => i.id);
    await expect(list(from.id)).resolves.toEqual([]);
    await expect(list(to.id)).resolves.toEqual([issue.id]);
  });
});

